TLM.f("Tempora/Pent24-2",{"officium":"Feria Tertia infra Hebdomadam XXIV post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent24-0","from":{"Introitus":"Tempora/Pent24-0","Oratio":"Tempora/Pent24-0","Lectio":"Tempora/Pent24-0","Graduale":"Tempora/Pent24-0","Evangelium":"Tempora/Pent24-0","Offertorium":"Tempora/Pent24-0","Secreta":"Tempora/Pent24-0","Communio":"Tempora/Pent24-0","Postcommunio":"Tempora/Pent24-0"},"sections":{"Introitus":[{"k":"ref","la":"Jer 29:11; 29:12; 29:14"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."}],"Oratio":[{"k":"text","la":"Excita, quǽsumus, Dómine, tuórum fidélium voluntátes: ut, divíni óperis fructum propénsius exsequéntes; pietátis tuæ remédia majóra percípiant."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses"},{"k":"ref","la":"Col 1:9-14"},{"k":"text","la":"Fratres: Non cessámus pro vobis orántes et postulántes, ut impleámini agnitióne voluntátis Dei, in omni sapiéntia et intelléctu spiritáli: ut ambulétis digne Deo per ómnia placéntes: in omni ópere bono fructificántes, et crescéntes in scientia Dei: in omni virtúte confortáti secúndum poténtiam claritátis ejus in omni patiéntia, et longanimitáte cum gáudio, grátias agentes Deo Patri, qui dignos nos fecit in partem sortis sanctórum in lúmine: qui erípuit nos de potestáte tenebrárum, et tránstulit in regnum Fílii dilectiónis suæ, in quo habémus redemptiónem per sánguinem ejus, remissiónem peccatórum."}],"Graduale":[{"k":"ref","la":"Ps 43:8-9"},{"k":"text","la":"Liberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti."},{"k":"text","la":"In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 24:15-35"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum vidéritis abominatiónem desolatiónis, quæ dicta est a Daniéle Prophéta, stantem in loco sancto: qui legit, intélligat: tunc qui in Judǽa sunt, fúgiant ad montes: et qui in tecto, non descéndat tóllere áliquid de domo sua: et qui in agro, non revertátur tóllere túnicam suam. Væ autem prægnántibus et nutriéntibus in illis diébus. Oráte autem, ut non fiat fuga vestra in híeme vel sábbato. Erit enim tunc tribulátio magna, qualis non fuit ab inítio mundi usque modo, neque fiet. Et nisi breviáti fuíssent dies illi, non fíeret salva omnis caro: sed propter eléctos breviabúntur dies illi. Tunc si quis vobis díxerit: Ecce, hic est Christus, aut illic: nolíte crédere. Surgent enim pseudochrísti et pseudoprophétæ, et dabunt signa magna et prodígia, ita ut in errórem inducántur - si fíeri potest - étiam elécti. Ecce, prædíxi vobis. Si ergo díxerint vobis: Ecce, in desérto est, nolíte exíre: ecce, in penetrálibus, nolíte crédere. Sicut enim fulgur exit ab Oriénte et paret usque in Occidéntem: ita erit et advéntus Fílii hóminis. Ubicúmque fúerit corpus, illic congregabúntur et áquilæ. Statim autem post tribulatiónem diérum illórum sol obscurábitur, et luna non dabit lumen suum, et stellæ cadent de cælo, et virtútes cœlórum commovebúntur: et tunc parébit signum Fílii hóminis in cœlo: et tunc plangent omnes tribus terræ: et vidébunt Fílium hóminis veniéntem in núbibus cæli cum virtúte multa et majestáte. Et mittet Angelos suos cum tuba et voce magna: et congregábunt eléctos ejus a quátuor ventis, a summis cœlórum usque ad términos eórum. Ab árbore autem fici díscite parábolam: Cum jam ramus ejus tener fúerit et fólia nata, scitis, quia prope est æstas: ita et vos cum vidéritis hæc ómnia, scitóte, quia prope est in jánuis. Amen, dico vobis, quia non præteríbit generátio hæc, donec ómnia hæc fiant. Cœlum et terra transíbunt, verba autem mea non præteríbunt."}],"Offertorium":[{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine."}],"Secreta":[{"k":"text","la":"Propítius esto, Dómine, supplicatiónibus nostris: et, pópuli tui oblatiónibus precibúsque suscéptis, ómnium nostrum ad te corda convérte; ut, a terrenis cupiditátibus liberáti, ad cœléstia desidéria transeámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc 11:24"},{"k":"text","la":"Amen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis."}],"Postcommunio":[{"k":"text","la":"Concéde nobis, quǽsumus, Dómine: ut per hæc sacraménta quæ súmpsimus, quidquid in nostra mente vitiósum est, ipsorum medicatiónis dono curétur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ba591f95b6d2e86d":{"t":"Jer 29, 11-12.14, Ps 84, 2\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva. (Ps 84, 2) Blagoslovio si, Gospodine, svoju zemlju, na dobro si okrenuo Jakovljevu sudbinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva.","kn":"perem. 29. 11-14). Govori Gospodin: Ja mislim misli mira, a ne cviljenja; prizivat ćete me i ja ću vas uslišati, i izvest ću robovanje vaše iz svih mjesta. (Ps. 84. 2) Blagoslovio si, Gospodine, zemlju svoju, povratio si roblje Jakovljevo. Slava Oću . . . Govori Gospodin .• •","knRef":"Kniewald 1942, str. 432–433 (snimka 217) (OCR)"},"cca8c715f38273c9":{"t":"<i>Pomolimo se</i>.\nPotakni, molimo, Gospodine, volju svojih vjernika, da oni, koji plod božanskoga djela revnije traže, veću pomoć tvoje dobrote prime.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":",- Potakni, molimo. Gospodine, volje svojih vjernika, das. većim pregnućem nastoje zadobiti plod. božanskih tajna i tako primiti veće, pomoći Tvoje dobrote, po G. n.","knRef":"Kniewald 1942, str. 440–441 (snimka 221) (OCR)"},"1709ed4b24525b57":{"t":"Kol 1, 9-14\nČitanje Poslanice bl. Pavla apostola Kološanima. Braćo: Ne prestajemo za vas moliti i prositi, da potpuno spoznate Božju volju sa svom mudrošću i duhovnim razumijevanjem; da živite dostojno Gospodina Boga ugađajući mu u svemu; da budete plodni svakim dobrim djelom i da napredujete u spoznaji Boga; da ojačani u svakoj kreposti njegovom slavom i moći podnosite sve potpuno strpljivo, velikodušno i radosno, da zahvaljujete Bogu Ocu koji nas učini dostojnima da budemo subaštinici svetaca u svjetlosti. On nas izbavi od vlasti tame i prenese u kraljevstvo svojega ljubljenog Sina, u kojem po njegovoj krvi imamo otkup i oprost grijeha.","kn":"Čitanje poslanice bi. Pavla apostola Kološanlma (1, 9-14). Braćo! Ne prestajerno za vas moliti i prositi, da ‘Potpuiio upoznate Božju volju Sa svakom mudrošću i duhovnim razumijevanjem. Đa živite dostojno Boga ugađajući mu u svemu: da budete plodni 'svakim dobrim djelom 1 napredujete u sppznaii Boga. Da ojačam i u svakoj kreposti po njegovoj slavnoj moći, podnosite sve potpuno strpljivo. r velikodušno i radosno. Da zahvaljujete Bogu Ocu, koji nas učini dostojnima, da budemo sudionici nasljedstva svetaca u svjetlosti. On nas izbavi od vlasti tame i prenese u kt aljevstvo svoga ljubljenoga Sina, u kojemu imamo po njegovoj krvi otkup, oprost grijeha.","knRef":"Kniewald 1942, str. 440–441 (snimka 221) (OCR)"},"a8b02c4b81c26ed7":{"t":"Ps 43, 8-9\nSpasio si nas, Gospodine, od naših protivnika i smeo si naše mrzitelje. U Bogu je naša slava u svako doba, i uvijek hvalimo ime tvoje.\n\nPs 129, 1-2\n<i>Aleluja</i>, <i>aleluja</i>.\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. <i>Aleluja</i>.","kn":"(Ps. 43, 8, 9). Oslobodio si nas, Gospodine, od onih, koji nas mučiše i smeo si one, koji mrziše na nas. U Bogu ćemo se hvaliti cijeli dan. 1 slavit ćemo ime Tvoje u vijeke.\n\nAleluja, aleluja. (Ps. 129, 1, 2) Iz dubine vapijem k Tebi, Gospodine; Gospodine usliši molitvu moju, aleluja. r","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"17f4871a7beb2a10":{"t":"Mt 24, 15-35\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Reče Isus svojim učenicima: Kad vidite na svetome mjestu groznu pustoš o kojoj govori prorok Danijel (koji čita neka razumije), tada oni koji su u Judeji neka bježe u gore, oni koji su na krovu neka ne silaze da što uzmu iz svoje kuće, oni koji su na polju neka se ne vraćaju da uzmu svoje haljine. A teško trudnicama i dojiljama u one dane! Molite da vaš bijeg ne bude zimi ili u subotu, jer će tada biti velika nevolja kakve nije bilo od postanka svijeta sve dosada niti će je biti. I kad se ne bi skratili oni dani, nitko se ne bi spasio. Ali radi izabranih skratit će se oni dani.« – Ako vam tko reče: »Evo, Krist je ovdje«, ili: »Krist je ondje«, nemojte vjerovati. Jer ustat će lažni kristi i lažni proroci, koji će činiti velike znakove i čudesa, da bi, ako je moguće, zaveli i izabrane. Eto, kazao sam vam unaprijed! Ako vam dakle reknu: »Eno ga u pustinji!« nemojte izlaziti; »Eno ga u tajnim odajama!«, nemojte vjerovati. Kao što munja izlazi od istoka i vidi se sve do zapada, tako će biti i dolazak Sina Čovječjega. Gdje god bude strvina, tamo će se i orlovi skupljati. Odmah poslije nevolje onih dana sunce će pomrčati, mjesec neće dati svoje svjetlosti, zvijezde će pasti s neba i pokrenut će se nebeske sile. I tada će se na nebu pokazati znak Sina Čovječjega. Na zemlji će proplakati sva plemena, kad ugledaju Sina Čovječjega gdje dolazi s neba na oblacima u veličanstvu i velikoj moći. I poslat će svoje anđele, koji će jakim glasom trublje skupiti sve njegove izabranike sa četiri strane svijeta, od jednoga do drugoga kraja neba. – Poukom neka vam bude primjer smokve: Kad se njezine grane pomlade i prolistaju, znate da je blizu ljeto. Tako i vi, kad sve to vidite, znajte da je blizu, pred vratima. Zaista vam kažem: Ovaj naraštaj neće proći dok se sve ovo ne ispuni. Nebo će i zemlja proći, ali riječi moje neće proći.","kn":"t Slijedi sveto evanđelje po Mateju (24, 15-35). U ono vrijeme reče Isus svojim učenicima; Kad vidite, da je na svetom mjestu gadna pustoš, o kojoj govori prorok Daniel (koji čita, neka razumije), tada, koji budu u Judeji, neka bježe u gore, i koji bude na krovu, neka ne silazi da što uzme iz svoje kuće, i koji bude na polju, neka se ne vraća natrag da uzme svoju haljinu. A teško trudnima i dojiljama u. one dane! Molite, da vaš bijeg ne bude zimi ili subotom. Jer tada će biti velika nevolja, kakve nije bilo od /potanka svijeta do sada, niti će je biti. I kad se ne bi skratili oni dani, nitko se ne bi spasio, ali će se oni dani skratiti radi izabranih. Ako vam tada tko reče: Evo, Krist je ovdje ili ondje, nemojte vjerovati. Jer će ustati lažni kristi i lažni proroci, koji će činiti velike znakove i čudesa, da bi, ako je moguće, zaveli i izabrane. Evo, kazao sam vam unaprijed. Ako vam, dakle, reknu: Eno ga u pustinji, nemojte izlaziti, evo ga u sobama, nemojte vjerovati. Jer kao što munja izlazi od Istoka i vidi se sve do zapada, tako će biti 1 dolazak Sina čovječjega. Gdjegod bude Iješina, tamo će se skupiti i orlovi. Odmah po nevolji onih dana sunce će iKKmrčati, mjesec ne će dati svoje svjetlosti, i zvijezde će padati s neba, i pokrenut će se nebeske sile. I tada će se pokazati znak Sina čovječjega na nebu, proplakat će sva plemena na zemlji, i vidjet te Sina čovječjega, gdje dolazi š velikom moći i veličanstvom na oblacima nebeskim. I poslat će svoje anđele, koji će jakim glasom trublje sabrati njegove izabrane od četiri strane svijeta, od jednoga do drugoga kraja neba. Naučite prispodobu od smoikve: Kad se njezine grane pomlade i prolistaju, znate, da je blizu ljeto. Tako i vi, kad vidite . sve ovo, znajte, da je blizu pred vratima. Zaista vam kažem: Ovaj naraštaj ne će proći, dok se ne ispuni sve ovo. Nebo će i zemlja proći, ali ne će proći moje riječi.","knRef":"Kniewald 1942, str. 442–443 (snimka 222) (OCR)"},"8a9f1217916db598":{"t":"Ps 129, 1-2\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. Iz dubine vapijem k tebi, Gospodine.","kn":"(Ps. 129, 1-2). Iz dubine vapijem k Tebi, Gospodine; Gospodine, usliši molitvu moju; iz dubine vapijem k Tebi, Gospodine.","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"14fc2f6f59228a3e":{"t":"Milostiv budi, Gospodine, našim molbama, primi darove i molitve svoga puka i srca svih nas obrati k sebi, da oslobođeni od zemaljskih požuda prijeđemo na nebeske želje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Milostiv budi. Gospodine, molbama našim i primivši prinose i molitve puka svojega, svih nas srca k sebi obrati, da ^oslobođeni k nebeskim željama prijeđemo. Po G. n.","knRef":"Kniewald 1942, str. 442–443 (snimka 222) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"2a2aa3c192299041":{"t":"Mk 11, 24\nZaista vam kažem: Što god moleći zaištete, vjerujte da ćete dobiti, i bit će vam.","kn":"(Mk., 11, 24). Zaista vam kažem, štogod moleći zaištete, vjerujte, da ćete primiti, i bit će vam.","knRef":"Kniewald 1942, str. 432–433 (snimka 217) (OCR)"},"160125c0d7667f44":{"t":"<i>Pomolimo se</i>.\nPodaj nam, molimo, Gospodine, da ova otajstva što ih primismo svojim spasonosnim darom iscijele što je god nevaljalo u našoj duši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti nam, molimo Te, Gospodine, da se krepošću ovih Svetinja, koje smo primili, iscijeli sve, što je grješno u našoj duši, po G. n. r Osim svetih vremena, koja se redaju oko najvećih kršćanskih blagdana, Božića i Uskrsa, svetkuje sv. Crkva i druge spomendane iz života Isusova i Marijina, kao i spomendane Božjih anđela i svetaca. Svetačke blagdane slavi sv. Crkva redovito u dan njihove zemaljske smrti, kad su Božji ugodnici unišli u vječni život. Svetački su blagdani u misalu poredani onim redoni, kako .slijede u crkvenoj godini^ koja počinje s onom nedjeljom, koja je najbliža svetkovini sv. Andrije apostola (30. XI.). Prema tomu počinje niz svetačkih blagdana u. crkvenoj godini s navečerjem sv. Andrije apostola 29. XI., a svršuje 26. XI. s blagdanom sv. Silvestra opata.","knRef":"Kniewald 1942, str. 442–443 (snimka 222) (OCR)"}}});
